1	// Shared value wrappers between the YAML loader and dumper.
2	//
3	// JavaScript's primitive types lose distinctions that PyYAML keeps after
4	// resolving a scalar (int vs float, string vs timestamp). The loader wraps
5	// those scalars in the classes below so the dumper can reproduce PyYAML's
6	// exact output.
7	//
8	// Value model produced by safeLoad() and consumed by safeDump():
9	//   - string        -> YAML str
10	//   - number (int)  -> YAML int
11	//   - boolean       -> YAML bool
12	//   - null          -> YAML null
13	//   - Array         -> YAML sequence
14	//   - plain Object  -> YAML mapping (keys are strings)
15	//   - YFloat        -> YAML float
16	//   - YTimestamp    -> YAML timestamp (date / datetime)
17	
18	export class YFloat {
19	  // value: a JS number. May be Infinity, -Infinity or NaN.
20	  constructor(value) {
21	    this.value = value;
22	  }
23	}
24	
25	export class YTimestamp {
26	  // text: the exact string PyYAML would emit for this timestamp
27	  // (e.g. "2020-01-01", "2001-12-15 02:59:43.1").
28	  constructor(text) {
29	    this.text = text;
30	  }
31	}

args.command:
chmod +x /output/tests/compare.sh
# Sanity: count cases and show a few reconstructed ones exactly as the harness will pass them
node -e '
const fs = require("fs");
const text = fs.readFileSync("/output/tests/cases.txt", "utf8");
const lines = text.split("\n");
if (lines[lines.length-1] === "") lines.pop();
const cases = []; let cur = [];
for (const l of lines) {
  if (l === "===") { if (cur.length) cases.push(cur); cur = []; }
  else cur.push(l);
}
if (cur.length) cases.push(cur);
console.log("total cases:", cases.length);
const show = i => console.log(i, JSON.stringify(cases[i].join("\n")));
[0, 48, 49, 69, 71, 72, 80, 91, 92, cases.length-2, cases.length-1].forEach(show);
// check for argparse-problematic single tokens starting with "-"
cases.forEach((c, i) => {
  const s = c.join("\n");
  if (s.startsWith("-") && !s.includes(" ") && !/^-\d/.test(s)) console.log("ARGPARSE RISK:", i, JSON.stringify(s));
});'

cat > /tmp/stub_ok.mjs <<'EOF'
// Throwaway harness-plumbing stub: delegates to the reference executable.
import { execFileSync } from 'node:child_process';
const idx = process.argv.indexOf('--a');
try {
  const out = execFileSync('/workspace/dataset/test16_executable', ['--a', process.argv[idx + 1]]);
  process.stdout.write(out);
} catch (e) {
  if (e.stdout) process.stdout.write(e.stdout);
  process.exit(e.status ?? 1);
}
EOF
cat > /tmp/stub_bad.mjs <<'EOF'
// Throwaway stub that is deliberately wrong.
console.log('WRONG');
EOF
echo '--- harness vs faithful stub (expect 99 pass) ---'
NODE_ENTRY=/tmp/stub_ok.mjs bash /output/tests/compare.sh | tail -3
echo "exit=$?"
echo '--- harness vs wrong stub (expect failures with diffs) ---'
NODE_ENTRY=/tmp/stub_bad.mjs bash /output/tests/compare.sh | head -12
NODE_ENTRY=/tmp/stub_bad.mjs bash /output/tests/compare.sh >/dev/null; echo "exit=$?"

