args.command:
grep '^FAIL' /tmp/real_run.txt | awk '{print $2}' | tr '\n' ' ' > /tmp/failed_nums.txt
node -e '
const fs=require("fs");
const failed=new Set(fs.readFileSync("/tmp/failed_nums.txt","utf8").trim().split(/\s+/).map(Number));
const text=fs.readFileSync("/output/tests/cases.txt","utf8");
const lines=text.split("\n"); if(lines.at(-1)==="") lines.pop();
const cases=[]; let cur=[];
for(const l of lines){ if(l==="==="){ if(cur.length) cases.push(cur.join("\n")); cur=[]; } else cur.push(l); }
if(cur.length) cases.push(cur.join("\n"));
for(let i=1;i<=cases.length;i++) if(!failed.has(i)) console.log(i, JSON.stringify(cases[i-1]));
console.log("ref=1 FAIL lines:", fs.readFileSync("/tmp/real_run.txt","utf8").match(/ref=1/g)?.length ?? 0);'
